#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("NO_INPUT\n");
        return 0;
    }

    long num1 = strtol(argv[1], NULL, 10);
    long num2 = strtol(argv[2], NULL, 10);

    if (num1 == 0 || num2 == 0) {
        printf("BAD_INPUT\n");
        return 0;
    }

    long remainder = num1;
    int count = 0;
    long quotients[200];

    while (remainder != 0 && count < 200) {
        long quotient = remainder / num2;
        quotients[count] = quotient;
        remainder -= quotient * num2;
        num2 = remainder;
        remainder = num1;
        num1 = num2;
        count++;
    }

    if (count == 200) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }

    printf("%ld", quotients[0]);
    for (int i = 1; i < count; i++) {
        printf("; %ld", quotients[i]);
    }
    printf("\n");

    return 0;
}
